(() => {
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const ui={intro:document.getElementById('intro'),ending:document.getElementById('ending'),dialog:document.getElementById('dialog'),choice:document.getElementById('choice'),toast:document.getElementById('toast'),objective:document.getElementById('objective'),questTitle:document.getElementById('questTitle'),questSub:document.getElementById('questSub'),hpFill:document.getElementById('hpFill'),willFill:document.getElementById('willFill'),hpText:document.getElementById('hpText'),willText:document.getElementById('willText'),moralText:document.getElementById('moralText'),moralFill:document.getElementById('moralFill')};
const W=2000,H=1450,keys={},mouse={x:480,y:300,down:false};let viewW=960,viewH=600,last=0,gameOn=false,mode='intro',moral=65,embers=0,toastTimer=0,shake=0;
const player={x:760,y:730,vx:0,vy:0,hp:100,will:100,face:0,attack:0,spell:0,dodge:0,inv:0,walk:0};
const dog={x:player.x-35,y:player.y+22,walk:0};
const keeper={x:490,y:600};const shrine={x:1510,y:490};
const enemies=[{x:320,y:920},{x:620,y:1080},{x:1010,y:980},{x:1270,y:750},{x:1650,y:900}].map((e,i)=>({...e,hp:3,alive:true,phase:i*1.7,hit:0,attack:0}));
const motes=[],particles=[];let lastAttack=0;
function resize(){const r=document.getElementById('game').getBoundingClientRect();viewW=960;viewH=Math.max(500,960*r.height/r.width);canvas.width=viewW*devicePixelRatio;canvas.height=viewH*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);}
window.addEventListener('resize',resize);resize();
function start(){ui.intro.classList.add('hidden');gameOn=true;mode='explore';toast('The lantern-keeper waits by the bridge.');}
document.getElementById('start').onclick=start;
document.getElementById('restart').onclick=()=>location.reload();
document.getElementById('accept').onclick=()=>{ui.dialog.classList.add('hidden');mode='hunt';ui.questTitle.firstChild.textContent='The ember hunt';ui.questSub.textContent='Gather five sparks in the mire.';ui.objective.textContent='Find and defeat the five ember-wisps.';toast('The keeper marks the old shrine on your map.');};
document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>finish(b.dataset.choice));
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=2.8;}
function finish(which){ui.choice.classList.add('hidden');mode='ending';if(which==='kind'){moral=Math.min(100,moral+32);ui.endingEyebrow.textContent='A gentle light';ui.endingTitle.innerHTML='The vale <span>blooms</span>';ui.endingText.textContent='You shared the fire. Warm windows kindle across the Gloaming Vale, and the keeper’s lantern shines brighter than ever. Somewhere at your heel, your loyal hound gives a happy bark. The people will speak your name with gratitude.';}else{moral=Math.max(0,moral-45);player.will=100;ui.endingEyebrow.textContent='A hungry light';ui.endingTitle.innerHTML='The vale <span>kneels</span>';ui.endingText.textContent='You bound the fire to your own heart. Power surges through you as the cottages fall dark. The hound stays close—but even it watches you differently now. The people will remember.';}ui.ending.classList.remove('hidden');}
function interaction(){if(!gameOn||mode==='ending')return;const dKeeper=Math.hypot(player.x-keeper.x,player.y-keeper.y),dShrine=Math.hypot(player.x-shrine.x,player.y-shrine.y);if(mode==='explore'&&dKeeper<100){ui.dialog.classList.remove('hidden');mode='dialog';return;}if(mode==='hunt'&&embers>=5&&dShrine<120){ui.choice.classList.remove('hidden');mode='choice';return;}if(mode==='hunt'&&embers<5&&dShrine<120)toast('The shrine is cold. Gather all five ember-sparks first.');else if(dKeeper<100)toast('Mara is waiting. Press E to hear her request.');else if(dShrine<130)toast(embers>=5?'Press E to choose the fate of the flame.':'The old shrine needs five ember-sparks.');else toast('Nothing nearby answers your call.');}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='e')interaction();if(k===' '&&!e.repeat)dodge();if(k==='q'&&!e.repeat)cast();});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)/r.width*viewW;mouse.y=(e.clientY-r.top)/r.height*viewH;});canvas.addEventListener('pointerdown',e=>{if(e.button===0){mouse.down=true;attack();}});window.addEventListener('pointerup',()=>mouse.down=false);
document.querySelectorAll('.touchbtn').forEach(b=>{const key=b.dataset.key,action=b.dataset.action;if(key){b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false));}else b.addEventListener('pointerdown',e=>{e.preventDefault();if(action==='attack')attack();if(action==='spell')cast();if(action==='dodge')dodge();if(action==='talk')interaction();});});
function attack(){if(!gameOn||['dialog','choice','ending'].includes(mode)||player.attack>0)return;player.attack=.32;const nearest=enemies.filter(e=>e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<118).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(nearest){nearest.hp--;nearest.hit=.28;const a=Math.atan2(nearest.y-player.y,nearest.x-player.x);nearest.x+=Math.cos(a)*38;nearest.y+=Math.sin(a)*38;burst(nearest.x,nearest.y,'#f3c76e',7);if(nearest.hp<=0)slay(nearest);}}
function cast(){if(!gameOn||mode==='dialog'||mode==='choice'||mode==='ending'||player.will<32||player.spell>0)return;player.will-=32;player.spell=.65;burst(player.x,player.y,'#8fe5da',32);enemies.forEach(e=>{if(e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<185){e.hp-=2;e.hit=.35;const a=Math.atan2(e.y-player.y,e.x-player.x);e.x+=Math.cos(a)*68;e.y+=Math.sin(a)*68;if(e.hp<=0)slay(e);}});}
function dodge(){if(!gameOn||player.dodge>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!dx&&!dy){dx=Math.cos(player.face);dy=Math.sin(player.face);}const l=Math.hypot(dx,dy)||1;player.vx=dx/l*570;player.vy=dy/l*570;player.dodge=.29;player.inv=.55;}
function slay(e){e.alive=false;embers++;motes.push({x:e.x,y:e.y-22,t:0});burst(e.x,e.y,'#ffc775',24);ui.objective.textContent=embers<5?`Ember-sparks gathered: ${embers} / 5`:'All five sparks gathered. Take them to the old shrine.';if(embers===5){ui.questSub.textContent='The shrine is awake. Choose your light.';toast('Five sparks! The old shrine glows to the east.');}}
function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=25+Math.random()*180;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,t:.35+Math.random()*.55,max:.9,color,size:2+Math.random()*4});}}
function update(dt){if(!gameOn)return;dt=Math.min(dt,.035);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}player.attack=Math.max(0,player.attack-dt);player.spell=Math.max(0,player.spell-dt);player.dodge=Math.max(0,player.dodge-dt);player.inv=Math.max(0,player.inv-dt);player.will=Math.min(100,player.will+dt*5.7);player.walk+=dt*8;
let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.face=Math.atan2(dy,dx);}const speed=player.dodge>0?570:220;const easing=player.dodge>0?1:Math.min(1,dt*12);player.vx+=(dx*speed-player.vx)*easing;player.vy+=(dy*speed-player.vy)*easing;if(!len&&player.dodge<=0){player.vx*=Math.max(0,1-dt*10);player.vy*=Math.max(0,1-dt*10);}player.x=Math.max(70,Math.min(W-70,player.x+player.vx*dt));player.y=Math.max(90,Math.min(H-80,player.y+player.vy*dt));
if(mouse.down&&performance.now()-lastAttack>450){attack();lastAttack=performance.now();}
for(const e of enemies){if(!e.alive)continue;e.phase+=dt;e.hit=Math.max(0,e.hit-dt);e.attack=Math.max(0,e.attack-dt);let ex=player.x-e.x,ey=player.y-e.y,d=Math.hypot(ex,ey);if(d<390){if(d>75){e.x+=ex/d*(58+Math.sin(e.phase)*8)*dt;e.y+=ey/d*(58+Math.sin(e.phase)*8)*dt;}else if(e.attack<=0&&player.inv<=0){player.hp-=9;player.inv=.8;e.attack=1.1;shake=.16;burst(player.x,player.y,'#e06b56',8);if(player.hp<=0)die();}}else{e.x+=Math.cos(e.phase)*8*dt;e.y+=Math.sin(e.phase*.7)*8*dt;}}
const target=enemies.filter(e=>e.alive).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];const dxDog=target?target.x- dog.x:player.x-50-dog.x,dyDog=target?target.y-dog.y:player.y+20-dog.y,dd=Math.hypot(dxDog,dyDog);if(dd>48){dog.x+=dxDog/dd*Math.min(dd,180*dt);dog.y+=dyDog/dd*Math.min(dd,180*dt);}dog.walk+=dt*10;
for(let i=motes.length-1;i>=0;i--){const m=motes[i];m.t+=dt;if(m.t>.75){motes.splice(i,1);continue;}if(Math.hypot(player.x-m.x,player.y-m.y)<44){m.t=.75;}}
for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;if(p.t<=0)particles.splice(i,1);}if(shake>0)shake-=dt;
ui.hpFill.style.width=Math.max(0,player.hp)+'%';ui.hpText.textContent=Math.max(0,Math.ceil(player.hp));ui.willFill.style.width=player.will+'%';ui.willText.textContent=Math.floor(player.will);ui.moralText.textContent=moral>68?'Kind':moral<35?'Feared':'Known';ui.moralFill.style.width=moral+'%';}
function die(){gameOn=false;mode='ending';ui.endingEyebrow.textContent='The mire claims another';ui.endingTitle.innerHTML='The light <span>fades</span>';ui.endingText.textContent='The ember-wisps overwhelm you. The keeper’s lantern flickers on, still waiting for a champion.';ui.ending.classList.remove('hidden');}

function seeded(n){let x=n|0;return()=>{x=(x*1664525+1013904223)|0;return(x>>>0)/4294967296;};}
const rand=seeded(71),grass=Array.from({length:650},()=>({x:rand()*W,y:rand()*H,s:2+rand()*5,a:rand()*6.28,c:rand()})),trees=[];
for(let i=0;i<190;i++){let x=rand()*W,y=rand()*H;if(Math.hypot(x-keeper.x,y-keeper.y)<145||Math.hypot(x-shrine.x,y-shrine.y)<140||Math.hypot(x-player.x,y-player.y)<150)continue;trees.push({x,y,r:18+rand()*21,h:32+rand()*43,shade:rand()});}
const flowers=Array.from({length:120},()=>({x:rand()*W,y:rand()*H,r:1+rand()*2,c:rand()}));
function draw(){const sx=Math.max(0,Math.min(W-viewW,player.x-viewW/2)),sy=Math.max(0,Math.min(H-viewH,player.y-viewH/2));ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*8,(Math.random()-.5)*8);ctx.translate(-sx,-sy);drawGround();drawPath();drawWater();drawWorldDecor();
const actors=[...trees.map(t=>({y:t.y,draw:()=>drawTree(t)})),{y:keeper.y,draw:drawKeeper},{y:shrine.y,draw:drawShrine},...enemies.filter(e=>e.alive).map(e=>({y:e.y,draw:()=>drawWisp(e)})),{y:dog.y,draw:drawDog},{y:player.y,draw:drawPlayer}].sort((a,b)=>a.y-b.y);actors.forEach(a=>a.draw());drawMotes();drawParticles();ctx.restore();drawMinimap(sx,sy);}
function drawGround(){const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#61795e');g.addColorStop(.45,'#718464');g.addColorStop(1,'#465f52');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// distant shadowed woodland edge
const edge=ctx.createLinearGradient(0,0,0,260);edge.addColorStop(0,'#243b35');edge.addColorStop(1,'#243b3500');ctx.fillStyle=edge;ctx.fillRect(0,0,W,280);
for(const p of grass){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.strokeStyle=p.c>.5?'#b6b57c22':'#293f3428';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(-p.s,0);ctx.quadraticCurveTo(0,-p.s*2,p.s,0);ctx.stroke();ctx.restore();}
for(const f of flowers){ctx.fillStyle=f.c>.7?'#e6ce8a99':f.c>.45?'#c9d7a270':'#e9eee050';ctx.beginPath();ctx.arc(f.x,f.y,f.r,0,Math.PI*2);ctx.fill();}
// light pools and soft vignette
for(const [x,y,r] of [[490,610,290],[1510,490,320],[790,740,260]]){let gl=ctx.createRadialGradient(x,y,0,x,y,r);gl.addColorStop(0,'#ead69a14');gl.addColorStop(1,'#ead69a00');ctx.fillStyle=gl;ctx.fillRect(x-r,y-r,r*2,r*2);}
}
function drawPath(){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';function road(width,color){ctx.beginPath();ctx.moveTo(300,520);ctx.bezierCurveTo(530,600,620,740,800,800);ctx.bezierCurveTo(1010,865,1160,760,1320,690);ctx.bezierCurveTo(1480,610,1500,540,1530,485);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
road(116,'#34473855');road(95,'#b4a277');road(84,'#c7b58b');road(3,'#e1d1a344');ctx.restore();
// worn cart track
ctx.save();ctx.strokeStyle='#7d765d58';ctx.lineWidth=2;ctx.setLineDash([9,18]);ctx.beginPath();ctx.moveTo(300,510);ctx.bezierCurveTo(550,610,640,740,800,800);ctx.bezierCurveTo(1030,870,1160,760,1320,690);ctx.bezierCurveTo(1470,620,1500,540,1530,485);ctx.stroke();ctx.restore();}
function drawWater(){ctx.save();ctx.beginPath();ctx.moveTo(900,0);ctx.bezierCurveTo(820,190,1030,330,900,480);ctx.bezierCurveTo(770,630,980,810,860,970);ctx.bezierCurveTo(760,1110,940,1270,850,1450);ctx.lineTo(1080,1450);ctx.bezierCurveTo(1150,1260,980,1120,1080,970);ctx.bezierCurveTo(1200,790,980,640,1080,490);ctx.bezierCurveTo(1180,340,980,180,1110,0);ctx.closePath();ctx.fillStyle='#426b68';ctx.fill();ctx.strokeStyle='#c2d2aa55';ctx.lineWidth=8;ctx.stroke();ctx.strokeStyle='#b8d5be38';ctx.lineWidth=2;for(let i=0;i<20;i++){let y=i*73+35,x=950+Math.sin(i*2)*28;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+35,y+7,x+66,y-2);ctx.stroke();}
// old stone crossing
ctx.fillStyle='#3d5148';ctx.fillRect(868,560,245,80);ctx.fillStyle='#ac9b75';ctx.fillRect(865,570,250,57);ctx.fillStyle='#d2c19a';ctx.fillRect(865,570,250,9);for(let x=880;x<1110;x+=39){ctx.fillStyle='#93866b';ctx.fillRect(x,582,32,8);ctx.fillRect(x,606,32,7);}ctx.restore();}
function drawWorldDecor(){// lantern glow markers
for(const [x,y,label] of [[keeper.x,keeper.y-56,'MARA'],[shrine.x,shrine.y-85,'OLD SHRINE']]){ctx.save();ctx.textAlign='center';ctx.font='10px Arial';ctx.letterSpacing='2px';ctx.fillStyle='#f0daa0aa';ctx.fillText(label,x,y);ctx.restore();}
// small distant stone cairns
for(const [x,y] of [[1170,1080],[390,1180],[1780,560],[1200,300]]){ctx.fillStyle='#253b35';ctx.beginPath();ctx.ellipse(x,y+9,17,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#83907a';ctx.beginPath();ctx.ellipse(x,y,12,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b6b599';ctx.beginPath();ctx.ellipse(x-2,y-5,8,5,0,0,Math.PI*2);ctx.fill();}}
function drawTree(t){const {x,y,r,h,shade}=t;ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#17291f';ctx.beginPath();ctx.ellipse(x+8,y+7,r*1.1,r*.42,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#604d37';ctx.fillRect(x-r*.16,y-h*.45,r*.32,h*.55);ctx.fillStyle='#806544';ctx.fillRect(x-r*.04,y-h*.43,r*.08,h*.44);
const colors=shade>.5?['#394f3b','#4a6342','#63764b']:['#30483b','#405b43','#536947'];for(let i=0;i<3;i++){ctx.fillStyle=colors[i];ctx.beginPath();ctx.ellipse(x+(i-1)*r*.37,y-h*.67+i*5,r*(.62-i*.04),h*(.21-i*.015),0,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#9b9b6955';ctx.beginPath();ctx.ellipse(x-r*.2,y-h*.79,r*.2,h*.06,-.3,0,Math.PI*2);ctx.fill();ctx.restore();}
function drawKeeper(){ctx.save();ctx.fillStyle='#17211d55';ctx.beginPath();ctx.ellipse(keeper.x,keeper.y+14,21,8,0,0,7);ctx.fill();ctx.fillStyle='#96764c';ctx.beginPath();ctx.moveTo(keeper.x-16,keeper.y+8);ctx.lineTo(keeper.x-13,keeper.y-24);ctx.lineTo(keeper.x+14,keeper.y-24);ctx.lineTo(keeper.x+18,keeper.y+8);ctx.closePath();ctx.fill();ctx.fillStyle='#c0a36d';ctx.fillRect(keeper.x-10,keeper.y-32,20,19);ctx.fillStyle='#e7c98a';ctx.beginPath();ctx.arc(keeper.x,keeper.y-37,9,0,7);ctx.fill();ctx.fillStyle='#33473a';ctx.beginPath();ctx.moveTo(keeper.x-14,keeper.y-38);ctx.lineTo(keeper.x,keeper.y-54);ctx.lineTo(keeper.x+15,keeper.y-38);ctx.closePath();ctx.fill();ctx.strokeStyle='#d8a754';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(keeper.x+17,keeper.y-5);ctx.lineTo(keeper.x+23,keeper.y-44);ctx.stroke();glow(keeper.x+23,keeper.y-46,8,'#ffc86e',.7);ctx.restore();}
function drawShrine(){ctx.save();glow(shrine.x,shrine.y-18,75,'#dfad62',.17);ctx.fillStyle='#263a33';ctx.beginPath();ctx.ellipse(shrine.x,shrine.y+5,58,27,0,0,7);ctx.fill();for(let i=0;i<5;i++){let a=i*6.28/5;let x=shrine.x+Math.cos(a)*39,y=shrine.y+Math.sin(a)*18;ctx.fillStyle=i%2?'#9c8c69':'#b4a179';ctx.beginPath();ctx.ellipse(x,y-15,11,22,a,0,7);ctx.fill();ctx.fillStyle='#d0c096';ctx.beginPath();ctx.ellipse(x,y-34,8,8,0,0,7);ctx.fill();}ctx.fillStyle='#e1bb70';ctx.beginPath();ctx.ellipse(shrine.x,shrine.y-36,15,20,0,0,7);ctx.fill();glow(shrine.x,shrine.y-38,29,'#f8ce79',.34);ctx.restore();}
function drawWisp(e){ctx.save();const pulse=.78+Math.sin(e.phase*3)*.17;glow(e.x,e.y-12,44,'#72d5c9',.33);ctx.globalAlpha=.28;ctx.fillStyle='#82d5cf';ctx.beginPath();ctx.ellipse(e.x,e.y+12,18,6,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=e.hit?'#fff5cd':'#88d8ce';ctx.beginPath();ctx.moveTo(e.x,e.y-31*pulse);ctx.bezierCurveTo(e.x+24,e.y-23,e.x+17,e.y+2,e.x+5,e.y+12);ctx.quadraticCurveTo(e.x-7,e.y+3,e.x-15,e.y+11);ctx.bezierCurveTo(e.x-24,e.y-4,e.x-14,e.y-23*pulse,e.x,e.y-31*pulse);ctx.fill();ctx.fillStyle='#203c3b';ctx.beginPath();ctx.arc(e.x-5,e.y-14,2.4,0,7);ctx.arc(e.x+5,e.y-14,2.4,0,7);ctx.fill();if(e.hp<3){ctx.fillStyle='#d78f74';ctx.fillRect(e.x-13,e.y-40,26*(e.hp/3),2);}ctx.restore();}

function drawDog(){const x=dog.x,y=dog.y+Math.sin(dog.walk)*1.5;ctx.save();ctx.fillStyle='#19251f55';ctx.beginPath();ctx.ellipse(x,y+7,19,7,0,0,7);ctx.fill();ctx.strokeStyle='#65472f';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x-14,y-2);ctx.quadraticCurveTo(x-25,y-15,x-22,y-20);ctx.stroke();ctx.fillStyle='#a97b4d';ctx.beginPath();ctx.ellipse(x,y-5,17,10,0,0,7);ctx.fill();ctx.fillStyle='#c39863';ctx.beginPath();ctx.ellipse(x+12,y-11,9,8,.2,0,7);ctx.fill();ctx.fillStyle='#754c38';ctx.beginPath();ctx.ellipse(x+18,y-10,3,4,.3,0,7);ctx.fill();ctx.fillStyle='#2c281d';ctx.beginPath();ctx.arc(x+14,y-14,1.5,0,7);ctx.fill();ctx.strokeStyle='#704d34';ctx.lineWidth=3;for(let i=-1;i<=1;i+=2){ctx.beginPath();ctx.moveTo(x+i*7,y+1);ctx.lineTo(x+i*7,y+8+Math.abs(Math.sin(dog.walk))*2);ctx.stroke();}ctx.restore();}
function drawPlayer(){ctx.save();const x=player.x,y=player.y+(player.dodge>0?Math.sin(player.dodge*10)*4:Math.sin(player.walk)*1.2);if(player.inv>0)ctx.globalAlpha=.48+Math.sin(performance.now()*.04)*.3;ctx.fillStyle='#17211e66';ctx.beginPath();ctx.ellipse(x,y+10,18,8,0,0,7);ctx.fill();ctx.strokeStyle='#332c25';ctx.lineWidth=5;for(const s of [-1,1]){ctx.beginPath();ctx.moveTo(x+s*7,y+1);ctx.lineTo(x+s*7,y+10);ctx.stroke();}ctx.fillStyle='#526e62';ctx.beginPath();ctx.moveTo(x-12,y+4);ctx.lineTo(x-10,y-19);ctx.lineTo(x+10,y-19);ctx.lineTo(x+13,y+4);ctx.closePath();ctx.fill();ctx.fillStyle='#9f8059';ctx.fillRect(x-9,y-21,18,6);ctx.fillStyle='#deb982';ctx.beginPath();ctx.arc(x,y-28,8,0,7);ctx.fill();ctx.fillStyle='#394d43';ctx.beginPath();ctx.moveTo(x-10,y-29);ctx.lineTo(x,y-43);ctx.lineTo(x+11,y-29);ctx.closePath();ctx.fill();
