(()=>{'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
const ui={intro:document.getElementById('intro'),ending:document.getElementById('ending'),dialog:document.getElementById('dialog'),choice:document.getElementById('choice'),toast:document.getElementById('toast'),objective:document.getElementById('objective'),questTitle:document.getElementById('questTitle'),questSub:document.getElementById('questSub'),hpFill:document.getElementById('hpFill'),willFill:document.getElementById('willFill'),hpText:document.getElementById('hpText'),willText:document.getElementById('willText'),moralText:document.getElementById('moralText'),moralFill:document.getElementById('moralFill')};
const W=2000,H=1450,keys={},mouse={x:480,y:300,down:false};let viewW=960,viewH=600,last=0,gameOn=false,mode='intro',moral=65,embers=0,toastTimer=0,shake=0;
const player={x:760,y:730,vx:0,vy:0,hp:100,will:100,face:0,attack:0,spell:0,dodge:0,inv:0,walk:0},dog={x:725,y:750,walk:0},keeper={x:490,y:600},shrine={x:1510,y:490};
