function resize(){const r=document.getElementById('game').getBoundingClientRect();viewW=960;viewH=Math.max(500,960*r.height/r.width);canvas.width=viewW*devicePixelRatio;canvas.height=viewH*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);}window.addEventListener('resize',resize);resize();
function start(){ui.intro.classList.add('hidden');gameOn=true;mode='explore';toast('The lantern-keeper waits by the bridge.');}document.getElementById('start').onclick=start;document.getElementById('restart').onclick=()=>location.reload();
document.getElementById('accept').onclick=()=>{ui.dialog.classList.add('hidden');mode='hunt';ui.questTitle.firstChild.textContent='The ember hunt';ui.questSub.textContent='Gather five sparks in the mire.';ui.objective.textContent='Find and defeat the five ember-wisps.';toast('The keeper marks the old shrine on your map.');};document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>finish(b.dataset.choice));
function toast(s){ui.toast.textContent=s;ui.toast.classList.add('show');toastTimer=2.8;}
