function interaction(){if(!gameOn||mode==='ending')return;let a=Math.hypot(player.x-keeper.x,player.y-keeper.y),b=Math.hypot(player.x-shrine.x,player.y-shrine.y);if(mode==='explore'&&a<100){ui.dialog.classList.remove('hidden');mode='dialog';return;}if(mode==='hunt'&&embers>=5&&b<120){ui.choice.classList.remove('hidden');mode='choice';return;}if(mode==='hunt'&&b<120)toast('The shrine is cold. Gather all five ember-sparks first.');else if(a<100)toast('Mara is waiting. Press E to hear her request.');else if(b<130)toast(embers>=5?'Press E to choose the fate of the flame.':'The old shrine needs five ember-sparks.');else toast('Nothing nearby answers your call.');}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='e')interaction();if(k===' '&&!e.repeat)dodge();if(k==='q'&&!e.repeat)cast();});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
