function dodge(){if(!gameOn||player.dodge>0)return;let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!x&&!y){x=Math.cos(player.face);y=Math.sin(player.face);}let l=Math.hypot(x,y)||1;player.vx=x/l*570;player.vy=y/l*570;player.dodge=.29;player.inv=.55;}
function slay(e){e.alive=false;embers++;motes.push({x:e.x,y:e.y-22,t:0});burst(e.x,e.y,'#ffc775',24);ui.objective.textContent=embers<5?`Ember-sparks gathered: ${embers} / 5`:'All five sparks gathered. Take them to the old shrine.';if(embers===5){ui.questSub.textContent='The shrine is awake. Choose your light.';toast('Five sparks! The old shrine glows to the east.');}}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=25+Math.random()*180;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,t:.35+Math.random()*.55,max:.9,color,size:2+Math.random()*4});}}
