let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.face=Math.atan2(dy,dx);}let speed=player.dodge>0?570:220,ease=player.dodge>0?1:Math.min(1,dt*12);player.vx+=(dx*speed-player.vx)*ease;player.vy+=(dy*speed-player.vy)*ease;if(!len&&player.dodge<=0){player.vx*=Math.max(0,1-dt*10);player.vy*=Math.max(0,1-dt*10);}player.x=Math.max(70,Math.min(W-70,player.x+player.vx*dt));player.y=Math.max(90,Math.min(H-80,player.y+player.vy*dt));if(mouse.down&&performance.now()-lastAttack>450){attack();lastAttack=performance.now();}
for(const e of enemies){if(!e.alive)continue;e.phase+=dt;e.hit=Math.max(0,e.hit-dt);e.attack=Math.max(0,e.attack-dt);let x=player.x-e.x,y=player.y-e.y,d=Math.hypot(x,y);if(d<390){if(d>75){e.x+=x/d*(58+Math.sin(e.phase)*8)*dt;e.y+=y/d*(58+Math.sin(e.phase)*8)*dt;}else if(e.attack<=0&&player.inv<=0){player.hp-=9;player.inv=.8;e.attack=1.1;shake=.16;burst(player.x,player.y,'#e06b56',8);if(player.hp<=0)die();}}else{e.x+=Math.cos(e.phase)*8*dt;e.y+=Math.sin(e.phase*.7)*8*dt;}}
const target=enemies.filter(e=>e.alive).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0],dxDog=target?target.x-dog.x:player.x-50-dog.x,dyDog=target?target.y-dog.y:player.y+20-dog.y,dd=Math.hypot(dxDog,dyDog);if(dd>48){dog.x+=dxDog/dd*Math.min(dd,180*dt);dog.y+=dyDog/dd*Math.min(dd,180*dt);}dog.walk+=dt*10;
for(let i=motes.length-1;i>=0;i--){motes[i].t+=dt;if(motes[i].t>.75)motes.splice(i,1);}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.97;p.vy*=.97;if(p.t<=0)particles.splice(i,1);}if(shake>0)shake-=dt;
ui.hpFill.style.width=Math.max(0,player.hp)+'%';ui.hpText.textContent=Math.max(0,Math.ceil(player.hp));ui.willFill.style.width=player.will+'%';ui.willText.textContent=Math.floor(player.will);ui.moralText.textContent=moral>68?'Kind':moral<35?'Feared':'Known';ui.moralFill.style.width=moral+'%';}
